    if not os.path.exists(file_path):
        return False, f"File does not exist: {file_path}"
    if os.path.getsize(file_path) == 0:
        return False, f"File is empty: {file_path}"
    return True, f"File exists and is not empty: {file_path}"

# Function to check if a CSV file has at least one row of data
def check_csv_has_data(file_path):
    try:
        with open(file_path, 'r') as csvfile:
            reader = csv.reader(csvfile)
            header = next(reader, None)
            if not header:
                return False, f"CSV file has no header: {file_path}"
            if not any(row for row in reader):
                return False, f"CSV file has no data rows: {file_path}"
        return True, f"CSV file has data rows: {file_path}"
    except Exception as e:
        return False, f"Error reading CSV file {file_path}: {str(e)}"

# Function to validate each output file
def validate_output_file(file_path):
