    exists, message = check_file_exists_and_not_empty(file_path)
    validation_results.append({
        "check_name": f"file_exists_and_not_empty_{os.path.basename(file_path)}",
        "passed": exists,
        "message": message
    })

    # Check if CSV file has at least one row of data
    if exists:
        has_data, message = check_csv_has_data(file_path)
        validation_results.append({
            "check_name": f"csv_has_data_{os.path.basename(file_path)}",
            "passed": has_data,
            "message": message
        })

# Main validation function
